mapper.select:
select

from tb_special_diagnosis 


		AND special_id = #{specialId}


		AND project_id = #{projectId}


		AND sub_image_id = #{subImageId}


		AND remark = #{remark}


		AND diagnosis_status = #{diagnosisStatus}


		AND status = #{status}


		AND delete_flag = #{deleteFlag}


		AND create_by = #{createBy}


		AND create_time = #{createTime}


		AND update_by = #{updateBy}


		AND update_time = #{updateTime}


		AND group_id = #{groupId}

SELECT t3.gender, CASE WHEN t3.gender = 0 THEN '雌性' WHEN t3.gender = 1 THEN '雄性' ELSE '未知' END AS 'sex', t3.group_name, t3.dosage, count( 1 ) total FROM tb_slide t1 LEFT JOIN tb_project t2 ON t1.project_id = t2.project_id LEFT JOIN tb_group t3 ON t1.group_id = t3.group_id WHERE t2.del_flag = 0 AND t3.del_flag = 0
AND t3.reasons = #{reasons}
AND t1.is_delete = 0
AND t2.special_id = #{specialId}
GROUP BY t3.gender, sex, t3.group_name, t3.dosage ORDER BY t3.gender DESC, sex, t3.group_name, t3.dosage

SELECT g2.total FROM ( SELECT ( SELECT g.gender FROM tb_group g WHERE g.group_id = p1.group_id ) gender, ( SELECT g.group_name FROM tb_group g WHERE g.group_id = p1.group_id ) group_name, ( SELECT g.dosage FROM tb_group g WHERE g.group_id = p1.group_id ) dosage, p1.sys_viscera, p2.sys_viscera_name, count( 1 ) total FROM ( SELECT aa.sys_viscera, aa.sys_position, aa.sys_grade, aa.sys_ddefinition, aa.sys_lesion, a.* FROM tb_special_diagnosis a LEFT JOIN ( SELECT special_diagnosis_id, group_concat( CASE WHEN dict_type = 'sys_viscera' THEN tags END ) sys_viscera, group_concat( CASE WHEN dict_type = 'sys_position' THEN tags END ) sys_position, group_concat( CASE WHEN dict_type = 'sys_lesion' THEN tags END ) sys_lesion, group_concat( CASE WHEN dict_type = 'sys_ddefinition' THEN tags END ) sys_ddefinition, group_concat( CASE WHEN dict_type = 'sys_grade' THEN tags END ) sys_grade FROM tb_special_diagnosis_detail GROUP BY special_diagnosis_id ) AS aa ON a.special_diagnosis_id = aa.special_diagnosis_id ) p1, ( SELECT aa.sys_viscera_name, aa.sys_position_name, aa.sys_grade_name, aa.sys_ddefinition_name, aa.sys_lesion_name, a.special_diagnosis_id FROM tb_special_diagnosis a LEFT JOIN ( SELECT special_diagnosis_id, group_concat( CASE WHEN dict_type = 'sys_viscera' THEN tag_name END ) sys_viscera_name, group_concat( CASE WHEN dict_type = 'sys_position' THEN tag_name END ) sys_position_name, group_concat( CASE WHEN dict_type = 'sys_lesion' THEN tag_name END ) sys_lesion_name, group_concat( CASE WHEN dict_type = 'sys_ddefinition' THEN tag_name END ) sys_ddefinition_name, group_concat( CASE WHEN dict_type = 'sys_grade' THEN tag_name END ) sys_grade_name FROM tb_special_diagnosis_detail GROUP BY special_diagnosis_id ) AS aa ON a.special_diagnosis_id = aa.special_diagnosis_id ) p2 WHERE p1.special_diagnosis_id = p2.special_diagnosis_id AND p1.special_id = #{specialId} AND p1.`status` = #{status}
AND p1.sys_grade = #{sysGrade}
GROUP BY gender, group_name, dosage, p1.sys_viscera, p2.sys_viscera_name ORDER BY gender DESC, group_name, dosage ) g2 WHERE g2.gender = #{gender} AND g2.group_name = #{groupName} AND g2.dosage = #{dosage} AND g2.sys_viscera_name = #{sysVisceraName}
